{
  "name": "@devvara/oc-omniroute-plugin",
  "version": "0.1.4",
  "description": "Independent OpenCode V2 plugin that connects OmniRoute as a custom provider and optionally routes native web search/fetch through OmniRoute REST.",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": {
      "import": "./server.js"
    }
  },
  "files": [
    "dist",
    "assets",
    "docs/configuration.md",
    "docs/migration.md",
    "server.js",
    "README.md",
    "LICENSE",
    "NOTICE"
  ],
  "scripts": {
    "clean": "rm -rf dist",
    "build": "tsup && tsc --emitDeclarationOnly --declaration --outDir dist",
    "typecheck": "tsc --noEmit",
    "test": "node --import tsx --import ./tests/setup.ts --test \"tests/**/*.test.ts\"",
    "prepublishOnly": "bun run clean && bun run build && bun run typecheck && bun run test"
  },
  "dependencies": {
    "zod": "^4.4.3"
  },
  "devDependencies": {
    "@opencode/plugin": "2.2.7",
    "@types/bun": "^1.4.4",
    "@types/node": "^22.20.5",
    "bun-types": "^1.4.4",
    "tsup": "^9.0.0",
    "tsx": "^4.23.15",
    "typescript": "^7.0.2"
  },
  "engines": {
    "node": ">=22.22.3"
  },
  "packageManager": "bun@1.4.4",
  "license": "MIT",
  "author": "devvara",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/devararishivian/opencode-omniroute.git"
  },
  "homepage": "https://github.com/devararishivian/opencode-omniroute#readme",
  "bugs": {
    "url": "https://github.com/devararishivian/opencode-omniroute/issues"
  },
  "keywords": [
    "omniroute",
    "opencode",
    "opencode-plugin",
    "opencode-v2",
    "ai-sdk",
    "openai-compatible",
    "provider",
    "catalog",
    "coding-agent",
    "ai-agent",
    "ai-gateway",
    "model-router",
    "web-search",
    "web-fetch"
  ],
  "publishConfig": {
    "access": "public"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.1.0 <3"
  }
}
